function test(name,run){testCase(name,{timeout:60_000},async t=>{const vectors=[],retain=(kind,value)=>{vectors.push({kind,value});return value;};try{await run(t,retain);}finally{if(process.env.ROUTER_FOOTPRINT_JSON_VECTOR_DIR){mkdirSync(process.env.ROUTER_FOOTPRINT_JSON_VECTOR_DIR,{recursive:true});writeFileSync(join(process.env.ROUTER_FOOTPRINT_JSON_VECTOR_DIR,Buffer.from(name).toString('hex')+'.json'),json({name,vectors},(_key,value)=>typeof value==='bigint'?{$integer:String(value)}:value)+'\n');}}});}
