 for(const [owner,wrap]of [[null,true],[Object.prototype,false],[Array.prototype,false],[Object.prototype,true],[Array.prototype,true]]){
  const item={...f.item,tokens:structuredClone(f.item.tokens)},observed=equal(retain,'full-hook-tape-'+(owner===Object.prototype?'Object':owner?'Array':'JSON')+'-'+wrap,jsonObservation(f,f.original,f.left,item,owner,wrap),jsonObservation(f,current,f.right,item,owner,wrap));assert.ok(observed.result.value);assert.ok(observed.tape.length);
  if(wrap){assert.equal(observed.tape.filter(row=>row.op==='stringify'&&row.receiver==='originalTokens').length,1);assert.equal(observed.tape.filter(row=>row.op==='stringify'&&row.receiver==='suppliedTokens').length,1);}
 }
